window.ATLAS_DATA={"subjects":{"etica":{"name":"Ética","icon":"ET","tone":"coral","subtitle":"Condutas, direitos e inclusão","description":"Jeitinho brasileiro: as duas faces, ética profissional, igualdade de tratamento, diversidade, acessibilidade e inclusão no trabalho.","points":[["Jeitinho — lado positivo","Criatividade, flexibilidade e improviso para resolver situações difíceis sem desrespeitar direitos."],["Jeitinho — lado negativo","Furar filas, favorecer conhecidos e contornar regras em benefício próprio gera desigualdade e desconfiança."],["Limite ético","Inovar dentro das regras é uma coisa; burlar regras para prejudicar outras pessoas é outra."],["Isonomia e impessoalidade","Critérios devem valer igualmente, sem privilégios pessoais indevidos."],["Ética profissional","Princípios que orientam a conduta no trabalho: honestidade, respeito, responsabilidade e integridade."],["Inclusão","Criar condições reais de participação e desenvolvimento para pessoas diferentes."],["Acessibilidade","Retirar barreiras físicas, digitais, comunicacionais e organizacionais."],["Igualdade e equidade","Igualdade é tratar com o mesmo respeito; equidade é remover barreiras que impedem acesso efetivo às oportunidades."],["Ações concretas","Combater estereótipos e assédio, oferecer tecnologias acessíveis, apoio e flexibilidade quando viável."],["Resultados organizacionais","Ambientes inclusivos podem melhorar criatividade, clima e retenção; inclusão não se resume a lucro."]],"pitfalls":["A criatividade não justifica corrupção ou desrespeito às regras.","Inclusão não é apenas contratar; é garantir participação e acessibilidade.","Equidade não é favoritismo: remove desvantagens e barreiras."],"sources":["E1","E2","E3"]},"leg":{"name":"Legislação","icon":"LE","tone":"blue","subtitle":"Trabalho, consumo e proteção","description":"CLT e vínculo empregatício, CTPS, direito do consumidor, ofertas e garantias, vendas casadas, stalking e provas digitais.","points":[["CLT e Constituição","A CLT foi consolidada em 1943 e disciplina relações trabalhistas; a Constituição também protege direitos."],["Vínculo de emprego","Pessoa física, pessoalidade, não eventualidade, subordinação e remuneração são elementos analisados em conjunto."],["Empregador","Assume riscos da atividade, dirige e remunera prestação de serviços."],["CTPS","Registro da relação de trabalho; a redação atual do art. 29 prevê cinco dias úteis para anotação, não 48h."],["CDC e relação de consumo","Normas que protegem o consumidor em relações com fornecedores de bens e serviços."],["Vulnerabilidade","Pode ser técnica, jurídica ou econômica, pois consumidores geralmente possuem menos poder ou informação."],["Inversão da prova","É uma possibilidade concedida pelo juiz nos termos legais; não acontece automaticamente em todo caso."],["Oferta e precificação","Informação suficientemente precisa vincula o fornecedor; divergência de preços favorece o menor, com discussão específica para erro evidente."],["Direito de arrependimento","Regra geral de sete dias para contratação fora do estabelecimento, como internet."],["Vício e prazo de reclamação","Prazo de 30 dias para não duráveis e 90 para duráveis, em regra para vícios aparentes."],["Cláusulas abusivas e venda casada","Não se pode impor desvantagem indevida ou condicionar uma compra à aquisição de outra."],["Stalking","Perseguição reiterada que viola liberdade ou privacidade, inclusive online; Lei 14.132/2021 inseriu art. 147-A."]],"pitfalls":["CTPS: material antigo traz 48h; a regra atual no art. 29 é cinco dias úteis.","Inversão do ônus da prova não é automática.","“Todo erro de etiqueta deve ser honrado” é generalização: erro grosseiro evidente exige análise do caso.","Stalking exige reiteração: uma crítica isolada não basta."],"sources":["L1","L2","L3","L4","L5","L6"]},"log":{"name":"Logística","icon":"LO","tone":"green","subtitle":"Materiais, fluxos e operações","description":"Administração de materiais, estoques, armazenagem, movimentação, logística integrada e tecnologias de controle.","points":[["Objetivo central","Garantir material adequado, na quantidade, no local e momento corretos, equilibrando qualidade e custo."],["Fluxo da área","Previsão de demanda → compra → recebimento → armazenagem → movimentação → expedição."],["Estoque","Protege operações contra falta, mas excesso representa custo, espaço e capital imobilizado."],["Inventário","Contagem física versus registros do sistema: encontra diferenças e corrige informações."],["Armazenagem","Receber, classificar, endereçar, conservar e organizar mercadorias."],["PEPS","Primeiro que entra, primeiro que sai: prioriza entrada mais antiga."],["PVPS","Primeiro que vence, primeiro que sai: prioriza validade próxima, especialmente para perecíveis."],["WMS","Sistema de gerenciamento de armazéns: localização, movimentações e controle operacional."],["Código de barras e RFID","Identificação e rastreabilidade: reduzem erros de localização e registros."],["Custos vs nível de serviço","Reduzir estoque demais pode gerar ruptura, atrasos e perda de clientes."],["Embalagem e manuseio","Proteção, facilidade de identificação, segurança, reaproveitamento e custo."],["Logística integrada","Conecta compras, produção, finanças, atendimento e distribuição."]],"pitfalls":["Logística não é só transporte.","Estoque zero nem sempre é eficiente: pode causar falta.","PEPS e PVPS não são a mesma coisa; validade é decisiva para perecíveis."],"sources":["G1","G2","G3"]},"dmn":{"name":"Desenvolvimento de Modelo de Negócio","icon":"DM","tone":"purple","subtitle":"Ideias, modelos e inovação","description":"Startups, Vale do Silício, inovação, riscos do crescimento, empreendedorismo e intraempreendedorismo.","points":[["Startup","Negócio jovem que experimenta uma solução inovadora e frequentemente busca escala."],["Vale do Silício","Ecossistema californiano com universidades, capital, empresas, talento e troca de conhecimento."],["Ecossistema importa","Uma boa ideia sozinha não substitui pessoas, recursos, testes e ambiente favorável."],["Escalabilidade","Capacidade de atender muito mais gente sem elevar custos na mesma proporção."],["Riscos de startups","Concorrência, falta de financiamento, dificuldade de validar demanda e mudanças de mercado."],["Empreendedorismo","Criar ou desenvolver um negócio assumindo responsabilidade por riscos e oportunidades."],["Intraempreendedorismo","Inovar dentro de uma organização existente, sem necessariamente ser proprietário."],["Exemplo da apostila","Funcionário do estoque sugere identificação por código e cores, reduzindo erros de separação."],["Condições para inovar","Autonomia, escuta, valorização de ideias, apoio da liderança e trabalho em equipe."],["Inovação aplicada","Propor solução é diferente de implementá-la, medir resultados e corrigir problemas."]],"pitfalls":["Toda startup é empresa jovem; nem toda empresa jovem é startup.","Funcionário que inova dentro da empresa é intraempreendedor, não necessariamente dono.","Inovação sem aceitação do mercado não garante sucesso."],"sources":["D1","D2"]}},"chapters":{"etica":[{"title":"Jeitinho brasileiro: criatividade ou vantagem indevida?","body":["O material didático apresenta o jeitinho brasileiro como uma maneira informal e improvisada de resolver problemas. Ele não é automaticamente bom nem ruim: importa o meio empregado e quem suporta suas consequências. Na dimensão positiva, o jeitinho expressa flexibilidade e capacidade de adaptação em situações difíceis. Uma família que substitui o passeio ao ar livre quando começa a chover resolve o imprevisto sem prejudicar ninguém.","Na dimensão negativa, a pessoa contorna uma regra para conseguir vantagem às custas dos outros. O exemplo das apostilas é alguém que fura uma fila porque quer fazer uma pergunta “rapidinha”. O pedido pode ser simples, mas as outras pessoas têm o mesmo direito à ordem de atendimento. O benefício individual produz um custo coletivo.","Para interpretar o tema, não caia na armadilha de dizer que toda improvisação é desonesta ou de defender qualquer atalho como criatividade. O critério é avaliar se há respeito à lei, às pessoas e às regras justas. Uma solução criativa respeitosa é diferente de privilégio, fraude ou favorecimento."],"example":"Uma escola muda o horário de uma atividade por chuva: adaptação. Um aluno consegue nota alterada por amizade: favorecimento.","oral":"O jeitinho é positivo quando resolve problemas com criatividade sem prejudicar os outros; é negativo quando fura regras e cria privilégios.","sources":["E1","E2"]},{"title":"Isonomia, impessoalidade e confiança coletiva","body":["Isonomia significa aplicar critérios de forma igual a pessoas em situações equivalentes. Impessoalidade significa decidir por critérios objetivos, não por simpatias e relações particulares. Esses princípios ajudam a compreender por que o jeitinho negativo enfraquece a confiança na sociedade e nas instituições.","Quando um funcionário agiliza uma contratação apenas porque conhece alguém, a questão não é só a pessoa beneficiada. Outros candidatos perdem a oportunidade de concorrer em igualdade. Se o mesmo critério for aplicado repetidamente, o grupo deixa de acreditar que as regras têm valor.","As apostilas relacionam uma sociedade mais ética à educação para cidadania, à valorização do bem coletivo, à transparência das instituições e à responsabilização por condutas desonestas. Ao estudar este tema, pergunte sempre: “Essa solução poderia ser oferecida a qualquer pessoa nas mesmas condições?” Se não, pode haver privilégio."],"example":"Uma empresa estabelece critérios públicos de seleção e registra as justificativas das decisões.","oral":"Uma regra ética deve valer igualmente; exceções por amizade enfraquecem a confiança e prejudicam quem cumpre as regras.","sources":["E1"]},{"title":"Ética profissional: o que orienta condutas no trabalho","body":["Ética profissional reúne princípios que orientam como trabalhadores e equipes agem em relação a colegas, clientes, fornecedores e à própria organização. As apostilas destacam honestidade, respeito, responsabilidade e integridade. Códigos de ética podem orientar situações próprias de cada profissão, mas regras escritas não substituem julgamento responsável.","Um empregado que encontra erro em um registro não deveria escondê-lo para parecer mais eficiente. A atitude profissional é comunicar, corrigir e prevenir novas falhas. Da mesma forma, a empresa não deve usar metas financeiras para justificar assédio, fraude ou desrespeito às pessoas.","Uma resposta forte de estudo separa resultado e meio: não basta a decisão trazer lucro ou velocidade. Também importa como o resultado foi obtido. Práticas antiéticas podem destruir confiança de clientes, trabalhadores e investidores, prejudicando a própria organização."],"example":"Um vendedor recusa omitir defeito conhecido de um produto para bater a meta.","oral":"Ética profissional é agir com honestidade, respeito e responsabilidade, mesmo quando uma atitude incorreta traria vantagem imediata.","sources":["E1"]},{"title":"Diversidade, inclusão, igualdade e equidade","body":["Diversidade descreve a presença de pessoas com diferentes características e experiências. Inclusão significa criar condições para que essas pessoas participem de verdade, sejam ouvidas e tenham oportunidades de desenvolvimento. Uma empresa pode ter trabalhadores diversos e ainda ser pouco inclusiva se mantém barreiras e práticas discriminatórias.","Igualdade envolve o mesmo respeito e reconhecimento de direitos. Equidade considera que pessoas enfrentam barreiras diferentes e pode exigir medidas adequadas para que consigam participar em condições justas. O objetivo não é favorecer arbitrariamente alguém, mas reduzir obstáculos que impedem o acesso real.","O documento sobre inclusão destaca que diversidade também amplia perspectivas e pode ajudar organizações a compreender públicos diferentes, promover inovação e melhorar o ambiente de trabalho. Esses benefícios são relevantes, mas o respeito à dignidade das pessoas não depende de retorno financeiro."],"example":"Oferecer um único formato inacessível de inscrição não garante oportunidade real para todos, mesmo que a regra seja idêntica.","oral":"Diversidade é ter diferenças presentes; inclusão é garantir participação real, removendo barreiras e respeitando as pessoas.","sources":["E3"]},{"title":"Acessibilidade: como tirar as barreiras na prática","body":["Acessibilidade no trabalho não se resume à existência de uma rampa. O material menciona adaptações de infraestrutura, comunicação, tecnologias, políticas e rotinas, para que diferentes pessoas possam atuar com autonomia e segurança. Uma plataforma digital inacessível ou uma informação apresentada de uma única maneira pode excluir tanto quanto uma porta inadequada.","O texto didático lista cinco caminhos: evitar preconceitos e estereótipos; combater assédio e discriminação; construir relações de apoio; garantir instalações e tecnologias acessíveis; e oferecer flexibilidade quando viável. Também destaca a necessidade de liderança comprometida e comunicação aberta.","Para responder “o que uma empresa realmente deve fazer?”, prefira citar medidas concretas: adaptar ferramentas, escutar necessidades, capacitar equipes, combater discriminação e monitorar se as pessoas conseguem exercer suas funções com qualidade e dignidade. Contratar alguém não encerra a obrigação de incluir."],"example":"Um sistema com leitura acessível, comunicação clara e apoio da equipe facilita a participação de pessoas diferentes.","oral":"Uma empresa inclusiva não apenas contrata: adapta ambientes e tecnologias, combate discriminação e permite participação real.","sources":["E3"]},{"title":"Pegadinhas de Ética — aplicar, não decorar","body":["A primeira pegadinha é confundir criatividade com corrupção: nem todo improviso viola regras. A segunda é achar que um benefício a um amigo é justo porque parece pequeno; o impacto sobre terceiros também conta. A terceira é dizer que igualdade significa tratar todas as situações de maneira mecânica, ignorando barreiras reais.","A quarta é confundir diversidade com inclusão: números de contratação, sozinhos, não demonstram que as pessoas têm voz, acesso e oportunidades. A quinta é acreditar que o lucro torna uma atitude ética. Avalie quem ganha, quem perde, quais direitos são afetados e se a justificativa valeria para todos.","Em 20 segundos, não tente reproduzir toda a teoria. Defina o conceito em uma frase e dê um exemplo reconhecível. Quando outra pessoa generalizar (“sempre”, “nunca”, “todo mundo”), procure a exceção que o próprio material apresenta."],"example":"Pergunta: “Se deu certo, foi ético?” Resposta: “Não necessariamente; é preciso analisar se houve respeito a direitos e às outras pessoas.”","oral":"O critério é simples: solução criativa respeita direitos; vantagem indevida prejudica pessoas ou ignora regras.","sources":["E1","E2","E3"]}],"leg":[{"title":"CLT e Direito do Trabalho: por que existem?","body":["A Consolidação das Leis do Trabalho reúne regras centrais das relações de emprego no Brasil. Foi aprovada pelo Decreto-Lei nº 5.452, em 1º de maio de 1943, no governo da época, e entrou em vigor em novembro daquele ano. O material explica que a CLT reuniu e regulamentou normas em um contexto de industrialização e urbanização.","Seu papel é organizar direitos e obrigações no trabalho, como regras relativas a jornada, descanso, salário, férias, registro e condições de trabalho. A CLT não é a única fonte: a Constituição e outras normas também protegem trabalhadores.","Ao estudar este tema, não reduza a legislação à ideia de “benefícios para o funcionário”. Ela estabelece previsibilidade para as duas partes: empregados sabem que proteção exigir; empregadores conhecem obrigações e riscos. Nem toda prestação de serviço, porém, caracteriza emprego regido pela CLT."],"example":"Um trabalhador precisa saber horários e direitos; a empresa precisa organizar contratos e pagamentos de forma regular.","oral":"A CLT organiza as relações de emprego e estabelece direitos e deveres, complementada pela Constituição e outras normas.","sources":["L1","L2"]},{"title":"Vínculo de emprego e responsabilidades do empregador","body":["A apostila de Direito do Trabalho descreve cinco elementos usados para reconhecer uma relação de emprego: prestação por pessoa física, pessoalidade, não eventualidade, subordinação e salário. A pessoalidade indica que a pessoa contratada executa o serviço; não eventualidade sugere prestação com continuidade; subordinação diz respeito à direção da atividade; e onerosidade significa pagamento.","A empresa empregadora assume os riscos da atividade econômica, contrata, remunera e dirige a prestação do trabalho. Isso importa porque o risco normal do negócio não deve ser simplesmente transferido ao empregado. O texto também explica que associações e instituições sem fins lucrativos podem ser equiparadas a empregadores quando contratam empregados.","Pegadinha comum: escrever “prestador autônomo” no contrato não resolve sozinho a natureza real da relação. O que acontece concretamente no trabalho precisa ser analisado à luz dos requisitos. Outra pegadinha: não se exige exclusividade absoluta em todos os vínculos empregatícios."],"example":"Uma pessoa trabalha pessoalmente de modo contínuo, recebe salário e segue direção do contratante: há indícios de vínculo.","oral":"Vínculo depende da realidade do trabalho: pessoa física, pessoalidade, não eventualidade, subordinação e remuneração.","sources":["L2"]},{"title":"CTPS: registro e o cuidado com material antigo","body":["A Carteira de Trabalho e Previdência Social registra informações importantes da relação de emprego. A apostila que trata de apresentação e devolução da carteira menciona prazos antigos de 48 horas. Como a legislação passou por atualizações, esse dado deve ser lido com atenção.","Na redação atual do art. 29 da CLT, o empregador tem cinco dias úteis para realizar as anotações de admissão, remuneração e condições especiais quando houver. Essa observação é uma verificação complementar na legislação oficial, não uma alteração silenciosa da apostila da professora. A CTPS Digital também integra as rotinas atuais.","Se perguntarem sobre prazo, a melhor resposta é distinguir: “Na apostila aparece a referência antiga a 48 horas; no art. 29 atual são cinco dias úteis para anotação”. Evite confundir prazo de anotação, registro da admissão e devolução de documento físico, que são questões diferentes."],"example":"Um estudodor cita 48 horas por memória; o outro explica que a regra do art. 29 foi modificada.","oral":"O art. 29 atual prevê cinco dias úteis para anotação na CTPS; a apostila traz texto anterior a essa mudança.","sources":["L2","L1"]},{"title":"Direito do Consumidor: quem é protegido e por quê?","body":["O Direito do Consumidor disciplina relações entre quem recebe produtos ou serviços como destinatário final e quem os fornece no mercado. O Código de Defesa do Consumidor (CDC) oferece proteção específica porque consumidor e fornecedor geralmente não possuem as mesmas informações e recursos.","As apostilas classificam a vulnerabilidade em três formas: técnica, quando o comprador não domina as características do produto; jurídica ou científica, quando desconhece direitos ou aspectos especializados; e econômica, quando dispõe de menor poder financeiro. Uma mesma pessoa pode apresentar mais de uma vulnerabilidade.","A inversão do ônus da prova é uma possibilidade prevista no CDC, sujeita aos requisitos e à avaliação judicial, e não uma regra automática que sempre obriga a empresa a provar tudo. Em uma discussão, diferencie a ideia geral de proteção do consumidor da aplicação específica de um mecanismo processual."],"example":"Cliente compra aparelho que não sabe consertar; fabricante conhece as características técnicas. Há assimetria de informação.","oral":"O CDC protege o consumidor por sua vulnerabilidade técnica, jurídica ou econômica; inversão da prova não é automática.","sources":["L3"]},{"title":"Preço, oferta, contratos e cláusulas abusivas","body":["A aula 2 de Direito do Consumidor aborda divergências entre o preço anunciado e o cobrado. Como regra, informações claras e precisas vinculam o fornecedor e, em divergências comuns, prevalece o menor preço anunciado. O material ressalta a hipótese de erro grosseiro, perceptível, que não deve servir para alguém se beneficiar de má-fé. Por isso, respostas absolutas como “qualquer preço de etiqueta sempre vale” são frágeis.","Os contratos devem ser claros e permitir que o consumidor entenda as regras, especialmente nos contratos de adesão. O texto cita fonte mínima de 12 pontos nesse tipo de instrumento. Cláusulas abusivas podem criar desvantagem exagerada e restringir direitos de forma incompatível com o CDC.","Exemplos das apostilas: cláusula que reduz indevidamente a responsabilidade por dano, proíbe a devolução quando a lei a assegura, impede o consumidor de procurar a Justiça ou prevê perda total das parcelas já pagas em certas situações de inadimplemento. Venda casada significa condicionar a aquisição de um item à contratação de outro, prática proibida."],"example":"Ao comprar um aparelho, a loja diz que só vende se o cliente contratar garantia adicional obrigatória: problema de venda casada.","oral":"Ofertas claras vinculam o fornecedor; cláusula abusiva cria desvantagem indevida, e venda casada condiciona uma compra a outra.","sources":["L4"]},{"title":"Arrependimento, problemas no produto e reclamações","body":["Nas contratações realizadas fora do estabelecimento, como compras pela internet ou telefone, o CDC prevê, em regra, direito de arrependimento em sete dias contados da assinatura ou recebimento, conforme o caso. A apostila lembra que a restituição deve abranger valores pagos, inclusive frete, quando aplicável. Essa regra não equivale a uma devolução gratuita e irrestrita de toda compra presencial sem motivo.","As aulas também diferenciam vícios de produtos e os prazos gerais para reclamar de vícios aparentes: 30 dias para produtos e serviços não duráveis e 90 dias para duráveis. Nos vícios ocultos, o início da contagem recebe tratamento próprio. Não confunda esses prazos de reclamação com a garantia contratual anunciada.","A responsabilidade por danos decorrentes de produto ou serviço defeituoso pode alcançar diferentes integrantes da cadeia, conforme o caso; o comerciante tem situações específicas de responsabilização indicadas na apostila. Para reclamar, é útil guardar comprovantes, registros do problema e contatos com o fornecedor. A discussão pode envolver órgãos de defesa do consumidor e medidas judiciais."],"example":"Compra online com desistência dentro de sete dias é caso típico do art. 49, diferente de desistir sem justificativa de compra presencial.","oral":"Fora da loja, a regra geral é arrependimento em sete dias; vício aparente tem prazos de 30 ou 90 dias conforme a durabilidade.","sources":["L3","L4"]},{"title":"Perseguição digital: stalking e diferenças entre crimes","body":["A Lei nº 14.132/2021 inseriu no Código Penal o crime de perseguição, conhecido como stalking. O núcleo da conduta é perseguir alguém reiteradamente, por qualquer meio, ameaçando integridade ou perturbando liberdade ou privacidade. Isso pode ocorrer presencialmente ou pela internet, como cyberstalking.","O documento da professora diferencia essa conduta de outros atos: calúnia envolve atribuição falsa de crime; difamação, imputação de fato ofensivo à reputação; injúria, ofensa à dignidade; e ameaça, promessa de mal injusto e grave. A publicação por meio digital não transforma automaticamente tudo em stalking.","A apostila orienta registrar evidências, preservar mensagens e links e procurar os canais competentes quando houver ocorrência. Para o estudo, evite confundir crítica isolada com perseguição repetida. E lembre: o objetivo é compreender a norma e proteger direitos, não rotular conflitos escolares comuns como crime sem os elementos legais necessários."],"example":"Mensagens insistentes de perseguição e perturbação da privacidade podem caracterizar situação distinta de uma crítica pontual.","oral":"Stalking é perseguição reiterada que invade ou perturba liberdade ou privacidade; uma crítica isolada não equivale automaticamente a esse crime.","sources":["L5"]},{"title":"Como responder pegadinhas jurídicas na análise","body":["A maior armadilha em Legislação é falar por absolutos. “Sempre”, “nunca” e “em qualquer hipótese” geralmente exigem cuidado. O consumidor é protegido, mas isso não quer dizer que toda reclamação seja automaticamente procedente ou que o juiz sempre inverta a prova. A etiqueta orienta o preço, mas erros grosseiros evidentes demandam análise específica.","No Direito do Trabalho, descrever um trabalhador como autônomo não elimina necessariamente uma relação de emprego; é preciso observar a realidade e seus requisitos. Na logística de uma empresa, isso também vale para negócios sem fins lucrativos que empregam pessoas.","Use um modelo oral simples: conceito → condição → exemplo. Diga o nome do direito, a situação em que ele vale e um caso que demonstre a regra. Nas perguntas de legislação, acrescentar a exceção relevante costuma valer mais do que repetir um artigo de memória sem compreender sua aplicação."],"example":"“A inversão da prova é automática?” “Não. Depende dos requisitos legais e de avaliação judicial no caso concreto.”","oral":"Direito precisa de condição e contexto: identifique o conceito, a regra e a exceção antes de responder.","sources":["L1","L2","L3","L4","L5"]}],"log":[{"title":"Logística e administração de materiais: visão integrada","body":["Logística é a área que coordena recursos, transporte, movimentação, armazenagem, pedidos e informações para que as atividades de uma organização aconteçam. A administração de materiais cuida do abastecimento, desde identificar a necessidade até comprar, receber, guardar, movimentar e distribuir itens. A ideia central do material é disponibilizar o produto certo, na quantidade, momento e lugar necessários, equilibrando qualidade e custo.","Logística não se limita ao caminhão de entrega. Uma compra mal planejada pode deixar o estoque vazio; um produto mal localizado pode atrasar a expedição; um pedido mal registrado pode comprometer o atendimento. O sistema precisa ser visto como uma cadeia conectada.","O material destaca que organizações públicas e sem fins lucrativos também precisam administrar recursos. Mesmo sem buscar lucro, precisam evitar desperdícios e garantir eficiência nos serviços."],"example":"A loja vende bem, mas não localiza o item no depósito: falha logística mesmo antes do transporte.","oral":"Logística integra materiais, armazenagem, transporte e informações para atender a demanda com qualidade e custos equilibrados.","sources":["G1","G2"]},{"title":"Compras, fornecedores e fluxo de abastecimento","body":["O fluxo começa quando a organização identifica quais materiais serão necessários e em que quantidade. Depois vêm seleção de fornecedores, negociação, pedido, recebimento e conferência. A etapa de compras não procura apenas o menor preço: também considera prazo, qualidade, confiabilidade e continuidade do fornecimento.","No recebimento, conferem-se quantidade, estado da embalagem e documentos. Na identificação e classificação, atribuem-se categorias e códigos. No endereçamento, define-se onde o produto ficará guardado, para que qualquer pessoa autorizada consiga localizá-lo.","Se a compra atrasa, a produção ou o atendimento pode parar. Se o recebimento não confere os itens, registros se tornam pouco confiáveis. São problemas que se propagam: por isso a logística moderna interliga compras, estoque, produção, finanças, fornecedores e clientes."],"example":"Fornecedor oferece preço baixo mas atrasa toda semana; o aparente desconto pode gerar custos de ruptura.","oral":"Boa compra avalia preço, qualidade, prazo e confiabilidade; o abastecimento envolve conferência, registro e localização.","sources":["G1","G2","G3"]},{"title":"Estoques: por que excesso e falta custam caro","body":["O estoque mantém itens disponíveis para consumo, produção ou venda e ajuda a lidar com incerteza na demanda e no abastecimento. Porém, manter materiais custa dinheiro: exige espaço, segurança, energia, movimentação e imobiliza capital. Produtos parados podem estragar, ficar obsoletos ou perder valor.","Por outro lado, trabalhar com estoque insuficiente pode resultar em ruptura: o cliente procura e não encontra o produto, ou a produção precisa parar. A administração de materiais busca o equilíbrio entre níveis de estoque, custo de manutenção e nível de serviço ao cliente, e não simplesmente acumular ou zerar mercadorias.","O controle considera previsão de consumo, tempo de reposição e política de compras. Se outra pessoa afirmar que “quanto menor o estoque, melhor”, responda perguntando como a empresa lidará com variações de demanda e atrasos de fornecedores."],"example":"Uma loja guarda 1000 itens que não vende e falta um produto popular: má gestão de estoque apesar do depósito cheio.","oral":"Estoque precisa equilibrar disponibilidade e custo; sobra imobiliza recursos e falta provoca ruptura.","sources":["G1","G2"]},{"title":"Armazenagem: etapas que evitam erros","body":["Armazenar não é jogar caixas num galpão. As etapas descritas no documento são recebimento, identificação, classificação, endereçamento, estocagem, controle de estoque, separação dos pedidos e expedição. Cada uma tem uma função específica: receber corretamente, localizar facilmente, conservar e entregar a mercadoria correta.","Existem diferentes formas de armazenagem: prateleiras para itens menores; porta-paletes para volumes paletizados; espaços refrigerados para itens sensíveis à temperatura; áreas a granel para grãos e outros materiais soltos; e sistemas automatizados para algumas movimentações e controles. A escolha depende do produto, segurança, espaço e custos.","Endereçamento merece atenção: é definir o local do item, não apenas colocar etiqueta. Um estoque grande sem locais registrados demora mais para ser operado e tem maior risco de erros. Um processo de expedição eficaz confere itens antes de enviá-los."],"example":"Produto A fica no corredor 2, prateleira B, nível 3: registro do endereço facilita a separação rápida.","oral":"Armazenagem eficaz envolve receber, identificar, endereçar, conservar, separar e expedir, tudo com controle.","sources":["G3"]},{"title":"Inventário, PEPS, PVPS e identificação de produtos","body":["Inventário é a conferência das quantidades existentes fisicamente em relação aos registros do sistema. Se aparecem 20 unidades registradas, mas 17 no estoque, existe diferença a investigar. A contagem ajuda a identificar perdas, erros de entrada, saída ou movimentação.","A apostila diferencia critérios para retirada de produtos: PEPS (primeiro que entra, primeiro que sai) dá prioridade às entradas mais antigas; PVPS (primeiro que vence, primeiro que sai) considera o prazo de validade. Em alimentos e medicamentos, um produto que vence antes costuma merecer prioridade mesmo que tenha chegado depois de outro lote.","Código de barras e identificação por radiofrequência, RFID, auxiliam rastreabilidade e registro. Eles não corrigem sozinhos processos ruins: quando um produto é cadastrado com dados errados, até um sistema automatizado pode reproduzir a falha. Conhecimento de inventário e de fluxo continua essencial."],"example":"Dois lotes: A chegou primeiro e vence em dezembro; B chegou depois e vence em novembro. Pelo PVPS, B sai antes.","oral":"Inventário confere físico e sistema. PEPS prioriza chegada; PVPS prioriza validade.","sources":["G2","G3"]},{"title":"Tecnologia e qualidade: o papel do WMS","body":["O WMS (Warehouse Management System) organiza operações de armazéns: endereços, movimentação, recebimento, separação, contagem e localização de produtos. O sistema melhora a visibilidade do fluxo e pode reduzir tempo de procura e erros. Mas tecnologia depende de procedimentos consistentes e cadastros confiáveis.","O material também mostra que embalagem e manuseio influenciam custo e proteção. Uma boa embalagem deve considerar resistência, identificação, facilidade de movimentação, custo, possibilidade de reaproveitamento e questões ambientais. Manuseio inadequado pode causar avarias e desperdício.","A decisão logística sempre relaciona custo e qualidade do serviço. Economizar no transporte ou no armazém, mas entregar com atraso ou danificar pedidos, pode piorar o resultado total da empresa. O estudo fica forte quando você conecta cada tecnologia a um problema concreto que ela ajuda a resolver."],"example":"WMS indica endereço certo, mas operador registra lote errado: o erro continua existindo; gestão e treinamento são indispensáveis.","oral":"WMS ajuda a controlar armazém, mas depende de informações corretas; reduzir custo sem cuidar do serviço pode sair caro.","sources":["G1","G3"]},{"title":"Como conectar logística às outras matérias","body":["Logística também exige ética: esconder perdas de inventário para parecer eficiente é uma conduta que compromete decisões. Exige legislação: relações com trabalhadores e consumidores geram obrigações. E admite intraempreendedorismo: o exemplo da apostila de DMN mostra um funcionário que propõe códigos e cores para reduzir erros na separação de mercadorias.","O melhor argumento de Logística em estudo não é decorar nomes de ferramentas; é compreender relações de causa e consequência. Estoque desorganizado causa atraso, que prejudica atendimento, que pode elevar custos e reduzir confiança. Um sistema pode ajudar, mas depende de pessoas e processos.","Em perguntas difíceis, responda com a lógica “objetivo → processo → risco”: qual recurso queremos manter disponível, o que faz a operação funcionar e qual prejuízo acontece quando falha. Dessa forma, você consegue defender variações de perguntas que nunca viu antes."],"example":"Pergunta: “Por que não eliminar todo o estoque?” Resposta: “Porque reposição e demanda são incertas; estoque bem dimensionado evita ruptura.”","oral":"Logística eficiente busca equilíbrio entre disponibilidade, custo, qualidade e informações confiáveis.","sources":["G1","G2","G3","D2"]}],"dmn":[{"title":"Startup: ideia inovadora não é sucesso garantido","body":["O material apresenta startups como empresas jovens que buscam desenvolver produtos, serviços ou soluções inovadoras. Muitas começam pequenas, recorrem à tecnologia e tentam alcançar clientes em larga escala. A palavra startup, porém, não significa simplesmente “qualquer empresa nova”: a noção de inovação e crescimento em ambiente de incerteza ajuda a distinguir o conceito.","Criar algo novo não garante demanda. O texto destaca riscos financeiros, concorrência e incerteza sobre aceitação de produtos. Por isso, conhecer o mercado, planejar, ouvir usuários e adaptar a solução importa tanto quanto criatividade ou tecnologia.","Em estudo, rejeite o mito do empreendedor que tem uma ideia brilhante e automaticamente prospera. É preciso demonstrar que o problema existe, que a solução resolve algo importante e que o negócio consegue operá-la de forma viável."],"example":"Um aplicativo sem usuários não se torna sucesso só porque foi desenvolvido com tecnologia de ponta.","oral":"Startup desenvolve solução inovadora sob incerteza; boa ideia precisa de mercado, execução e capacidade financeira.","sources":["D1"]},{"title":"Vale do Silício: por que o ecossistema importa","body":["O Vale do Silício fica na Califórnia, nos Estados Unidos, e se destacou como região concentradora de empresas de tecnologia, universidades, investidores e especialistas. O material cita organizações com forte ligação à região e descreve um ambiente que favorece troca de conhecimento e transformação de ideias em produtos.","Seu desenvolvimento não depende apenas de “pessoas geniais”. Universidades formam talentos e geram pesquisa, empresas criam experiências e demanda, investidores ajudam a financiar crescimento, e redes profissionais aproximam equipes e ideias. A combinação forma um ecossistema de inovação.","Também não significa que toda startup precise nascer ali. O material menciona expansão de iniciativas brasileiras em serviços digitais, educação, saúde, comércio e finanças. O exemplo do Vale do Silício serve para entender a importância do ambiente favorável, não para copiar automaticamente tudo que funciona nos Estados Unidos."],"example":"Pergunta: “O Vale do Silício é uma única empresa?” “Não; é uma região com instituições e negócios conectados.”","oral":"O Vale do Silício demonstra como universidades, capital, profissionais e cultura empreendedora fortalecem a inovação.","sources":["D1"]},{"title":"Crescimento, escalabilidade e riscos","body":["Empresas podem crescer vendendo mais, mas nem todo crescimento é facilmente escalável. Escalabilidade é um conceito complementar útil à discussão da apostila: capacidade de ampliar atendimento ou receita sem que custos precisem aumentar na mesma proporção. Uma solução digital pode ter oportunidades de escala, mas também enfrenta despesas com operação, suporte e infraestrutura.","O texto de startups menciona obstáculos reais: falta de capital, concorrência, aceitação incerta de produtos e necessidade de adaptação. Crescimento rápido, sem processos e recursos adequados, pode piorar a qualidade e a situação financeira.","A resposta mais forte é distinguir tecnologia, inovação, crescimento e resultado. Ter aplicativo não garante startup viável; receber investimento não garante cliente; aumentar faturamento não prova lucratividade. Essa diferenciação é uma extensão didática coerente com os riscos apontados na apostila, e não uma afirmação de que ela apresenta fórmulas financeiras específicas."],"example":"Se vendas duplicam, mas despesas triplicam, há crescimento de vendas, mas não evidência de crescimento eficiente.","oral":"Escala é crescer sem elevar custos na mesma proporção; a startup precisa validar demanda e administrar riscos.","sources":["D1"]},{"title":"Intraempreendedorismo: inovação sem ser dono","body":["Intraempreendedorismo é agir com iniciativa empreendedora dentro de uma empresa existente. A pessoa não precisa ser fundadora nem proprietária. Pode ser empregada que percebe problemas, apresenta melhorias e ajuda a implementá-las, aumentando eficiência, qualidade ou atendimento.","A apostila destaca responsabilidade, liderança, criatividade, comprometimento, aprendizado contínuo e colaboração. O intraempreendedor não fica limitado a cumprir instruções de maneira mecânica; observa processos e propõe aperfeiçoamentos. Contudo, a iniciativa precisa ser comunicada e compatível com as responsabilidades e regras do ambiente profissional.","Para a empresa, estimular sugestões pode reduzir desperdícios, melhorar produtividade e aumentar capacidade de adaptação. A liderança contribui quando dá espaço para ideias, reconhece esforços e promove diálogo. Se a equipe teme punição por sugerir melhorias, oportunidades podem permanecer invisíveis."],"example":"Atendente propõe um sistema mais claro de distribuição de senhas, reduzindo filas; inovou sem abrir empresa.","oral":"Intraempreendedor é quem propõe e ajuda a implantar melhorias dentro de uma empresa, sem precisar ser dono.","sources":["D2"]},{"title":"O exemplo do estoque: da observação ao resultado","body":["No exemplo da apostila, um funcionário de estoque observa erros frequentes na separação de mercadorias. Em vez de aceitar o problema como inevitável, propõe identificar produtos por códigos e cores. Com aprovação e implementação, a mudança reduz falhas, economiza tempo e melhora a organização.","Esse caso ensina três passos: perceber um problema real, propor solução prática e acompanhar se ela melhora o trabalho. Criatividade sozinha é insuficiente; a organização deve autorizar, testar e observar os resultados. A aplicação também demonstra como DMN e Logística se encontram em uma mesma situação.","Em estudo, quando perguntarem se intraempreender é “só dar ideias”, explique que uma ideia tem valor maior quando se transforma em melhoria concreta. E quando perguntarem se é “mandar na empresa”, explique que colaboração, liderança e respeito aos processos continuam necessários."],"example":"Código e cores para separar mercadorias: pequena mudança interna com grande efeito no processo.","oral":"O intraempreendedor identifica problemas e melhora processos; o caso dos códigos no estoque mostra inovação prática.","sources":["D2"]},{"title":"Comparações e perguntas difíceis de DMN","body":["Empreendedorismo tradicional envolve criar ou gerir um negócio próprio; intraempreendedorismo envolve agir com iniciativa dentro de uma organização existente. Startup é uma forma de empreendimento frequentemente associada à inovação e à busca de crescimento. Empresas tradicionais também podem inovar, e funcionários de ambos os tipos podem ser intraempreendedores.","Uma resposta fácil de memorizar é a matriz “problema → solução → teste → resultado”. Uma startup precisa entender qual problema de mercado resolve; uma inovação interna começa identificando uma dificuldade do trabalho; ambos ganham qualidade quando as mudanças são testadas e ajustadas.","A pergunta difícil costuma exagerar: “Toda ideia nova é startup?”, “O Vale do Silício sozinho garante sucesso?”, “Intraempreendedor precisa ter empresa?”. Em todos os casos, a resposta é não, seguida da distinção correta. Faça conexão com ética quando surgirem atalhos: inovação não justifica descumprir direitos nem prejudicar pessoas."],"example":"Uma empresa estabelecida cria novo processo; isso é inovação, mas não necessariamente criação de startup.","oral":"Startup busca inovar num negócio; intraempreendedor inova por dentro. Nenhum dos dois garante sucesso sem execução.","sources":["D1","D2","E1"]}]},"questions":[{"id":"Q01","cat":"etica","q":"O que é o jeitinho brasileiro?","short":"É uma forma informal de resolver problemas. Pode expressar criatividade, mas se burlar direitos ou regras e prejudicar outros, vira conduta antiética.","more":"As duas apostilas apresentam sua ambivalência: flexibilidade e criatividade de um lado, privilégio e corrupção cotidiana de outro.","src":"E1"},{"id":"Q02","cat":"etica","q":"Qual a linha entre criatividade e desonestidade?","short":"Criatividade resolve dificuldades sem violar direitos; desonestidade busca vantagem injusta, desrespeitando regras ou prejudicando terceiros.","more":"Trocar um passeio ao ar livre por uma atividade indoor é adaptação legítima; furar uma fila é privilégio injustificado.","src":"E2"},{"id":"Q03","cat":"etica","q":"Jeitinho brasileiro sempre é negativo?","short":"Não. A expressão também descreve soluções criativas e flexíveis. O problema surge quando há quebra de regras, privilégios e prejuízo coletivo.","more":"Há estudo cultural; a avaliação deve considerar a ação, seus impactos e o tratamento dispensado às outras pessoas.","src":"E1"},{"id":"Q04","cat":"etica","q":"Por que o jeitinho pode enfraquecer a confiança nas instituições?","short":"Porque normalizar privilégios transmite a ideia de que as regras valem só para alguns. Isso reduz confiança, igualdade e cooperação.","more":"A apostila associa o lado negativo à quebra da impessoalidade e à corrosão do civismo.","src":"E1"},{"id":"Q05","cat":"etica","q":"O que significam isonomia e impessoalidade?","short":"Isonomia significa critérios iguais; impessoalidade evita privilégios por amizade ou influência. Ambas sustentam decisões mais justas.","more":"Na prática: critérios transparentes para filas, contratações, promoções e atendimento.","src":"E1"},{"id":"Q06","cat":"etica","q":"O que é ética profissional?","short":"É o conjunto de princípios que orienta condutas no trabalho, como honestidade, respeito, responsabilidade e integridade.","more":"Códigos de ética específicos organizam expectativas, mas valores como honestidade e respeito são amplamente compartilhados.","src":"E1"},{"id":"Q07","cat":"etica","q":"Uma empresa pode ser eficiente e antiética ao mesmo tempo?","short":"Pode ter resultado financeiro de curto prazo, mas práticas antiéticas geram injustiças, danos à confiança e riscos para a organização.","more":"O material relaciona ética a reputação, relações internas e confiança de consumidores e investidores.","src":"E1"},{"id":"Q08","cat":"etica","q":"Qual a diferença entre diversidade e inclusão?","short":"Diversidade é haver pessoas diferentes; inclusão é garantir que elas participem, sejam respeitadas e tenham oportunidades reais.","more":"Uma equipe pode ser diversa no papel e excludente na rotina. A inclusão exige ações práticas e ambiente acessível.","src":"E3"},{"id":"Q09","cat":"etica","q":"O que é acessibilidade no ambiente de trabalho?","short":"É remover barreiras físicas, digitais e de comunicação para que pessoas possam trabalhar e participar de forma efetiva.","more":"Isso inclui instalações, ferramentas e práticas de trabalho adequadas às necessidades das pessoas.","src":"E3"},{"id":"Q10","cat":"etica","q":"Igualdade e equidade são a mesma coisa?","short":"Não. Igualdade trata pessoas com igual dignidade; equidade reconhece barreiras e ajusta condições para oferecer oportunidades reais.","more":"A leitura de inclusão defende igualdade de oportunidades e eliminação de barreiras que dificultam a participação.","src":"E3"},{"id":"Q11","cat":"etica","q":"Como responder a quem diz que inclusão reduz a produtividade?","short":"Inclusão bem implementada remove barreiras e aproveita talentos. Pode favorecer inovação, colaboração e retenção, além de ser uma questão de respeito.","more":"Não é só marketing: depende de compromisso da liderança, recursos, combate ao assédio e práticas acessíveis.","src":"E3"},{"id":"Q12","cat":"etica","q":"Cite três ações de uma empresa inclusiva.","short":"Combater assédio e preconceitos, disponibilizar ferramentas acessíveis e oferecer condições de participação e desenvolvimento.","more":"O material também sugere apoio entre colegas, treinamentos, instalações adequadas e flexibilidade quando possível.","src":"E3"},{"id":"Q13","cat":"etica","q":"Flexibilidade no trabalho é sempre sinônimo de jeitinho?","short":"Não. Flexibilidade legítima adapta processos de maneira transparente; jeitinho antiético cria exceções injustas ou descumpre regras.","more":"A comparação integra as duas apostilas de ética e inclusão: adaptação é positiva quando não viola direitos.","src":"E1/E3"},{"id":"Q14","cat":"etica","q":"Quando improvisar soluções passa a ser um risco?","short":"Quando o atalho ignora segurança, discrimina pessoas ou prejudica terceiros. A solução deve ser criativa e responsável.","more":"Exemplo: contornar um processo de segurança para ganhar velocidade pode produzir custo maior e danos.","src":"E2"},{"id":"Q15","cat":"leg","q":"O que a CLT regulamenta?","short":"Consolida regras das relações de trabalho, incluindo jornada, registro, descanso e proteção dos trabalhadores. Surgiu em 1943.","more":"A CLT organiza normas trabalhistas; não é a única fonte: Constituição e outras leis também importam.","src":"L1"},{"id":"Q16","cat":"leg","q":"Quais são os cinco elementos de vínculo de emprego?","short":"Pessoa física, pessoalidade, trabalho não eventual, subordinação e remuneração. Devem ser avaliados em conjunto.","more":"O art. 3º da CLT menciona pessoa física, dependência, não eventualidade e salário; a doutrina destaca pessoalidade.","src":"L2"},{"id":"Q17","cat":"leg","q":"Ter CNPJ impede alguém de ser reconhecido como empregado?","short":"Não necessariamente. A forma contratual não elimina, por si só, a análise de pessoalidade, habitualidade, remuneração e subordinação.","more":"É uma aplicação do conceito de vínculo da apostila; avaliação jurídica depende dos fatos concretos.","src":"L2"},{"id":"Q18","cat":"leg","q":"O que caracteriza o empregador?","short":"Quem assume os riscos da atividade econômica, admite, remunera e dirige a prestação de serviços.","more":"A apostila relaciona o conceito ao art. 2º da CLT e diferencia empregador da pessoa do empregado.","src":"L2"},{"id":"Q19","cat":"leg","q":"Qual é o prazo atual de anotação da CTPS?","short":"A redação atual do art. 29 da CLT prevê cinco dias úteis para anotações da admissão; a apostila antiga ainda menciona 48 horas.","more":"Essa é uma atualização conferida na CLT consolidada oficial. Não repetir o prazo antigo como regra atual.","src":"L2/ATUAL"},{"id":"Q20","cat":"leg","q":"Quem são consumidor e fornecedor?","short":"Consumidor adquire ou utiliza produto ou serviço como destinatário final; fornecedor oferece produtos ou serviços no mercado.","more":"O CDC protege a relação de consumo, que costuma apresentar desigualdade de conhecimento ou poder econômico.","src":"L3"},{"id":"Q21","cat":"leg","q":"Quais são as três vulnerabilidades discutidas no CDC?","short":"Técnica, jurídica e econômica: falta de conhecimento especializado, conhecimento legal ou poder econômico frente ao fornecedor.","more":"Apostila da aula 01 descreve as três e indica que algumas empresas também podem ser consumidoras em determinadas situações.","src":"L3"},{"id":"Q22","cat":"leg","q":"O juiz sempre inverte o ônus da prova a favor do consumidor?","short":"Não. A inversão depende das condições previstas no CDC e de decisão judicial; não é automática em toda reclamação.","more":"É um recurso para reduzir desigualdade probatória, sem presumir vitória do consumidor em qualquer disputa.","src":"L3"},{"id":"Q23","cat":"leg","q":"Produto com dois preços: qual vale?","short":"Em regra, prevalece o menor preço informado para o mesmo produto. Quando há erro grosseiro evidente, a solução exige avaliar o caso concreto.","more":"O material didático traz as duas situações; Procon também reconhece a excepcionalidade do erro claramente desproporcional.","src":"L4"},{"id":"Q24","cat":"leg","q":"Qual o prazo de arrependimento de uma compra online?","short":"Em regra, sete dias para desistir de contratação feita fora do estabelecimento, contados da assinatura ou do recebimento, conforme o caso.","more":"A aula 02 destaca internet e telemarketing e a restituição de valores relacionados à contratação, incluindo frete conforme aplicável.","src":"L4"},{"id":"Q25","cat":"leg","q":"O que é cláusula abusiva?","short":"É regra contratual que coloca o consumidor em desvantagem indevida ou restringe ilegalmente seus direitos.","more":"Exemplos da apostila: afastar responsabilidade indevidamente e obrigar consumidor a abrir mão do acesso à Justiça.","src":"L4"},{"id":"Q26","cat":"leg","q":"O que é venda casada?","short":"É condicionar a compra de um produto ou serviço à aquisição de outro que o consumidor não deseja.","more":"Exemplo didático: exigir contratação de seguro como condição inadequada para um empréstimo.","src":"L4"},{"id":"Q27","cat":"leg","q":"Qual a diferença dos prazos de reclamação de vício aparente?","short":"Trinta dias para produtos e serviços não duráveis; noventa dias para duráveis, conforme o CDC.","more":"Para vício oculto, o prazo começa quando o defeito se torna perceptível, segundo a aula 02.","src":"L4"},{"id":"Q28","cat":"leg","q":"Fornecedor responde mesmo sem ter culpa por acidente de consumo?","short":"Em diversas hipóteses de defeito do produto ou serviço, a responsabilidade é objetiva, observadas as regras e exceções legais.","more":"A aula diferencia fabricante e prestador de serviços e condições em que comerciante pode responder.","src":"L4"},{"id":"Q29","cat":"leg","q":"O que é stalking ou perseguição?","short":"É perseguir alguém repetidamente, por qualquer meio, afetando liberdade, privacidade ou integridade; pode ocorrer pela internet.","more":"A Lei 14.132/2021 inseriu art. 147-A no Código Penal, conforme material da aula e lei oficial.","src":"L5"},{"id":"Q30","cat":"leg","q":"Qual a diferença entre calúnia, difamação e injúria?","short":"Calúnia imputa falsamente crime; difamação atribui fato que ofende reputação; injúria atinge dignidade ou decoro.","more":"O material de perseguição também diferencia ameaça, caracterizada por anúncio de mal injusto e grave.","src":"L5"},{"id":"Q31","cat":"leg","q":"Como uma vítima deve preservar provas de perseguição online?","short":"Guardar capturas, links, datas e registros; procurar orientação e autoridade competente. O material também apresenta ata notarial como opção.","more":"A apostila recomenda registro imediato, preservação de URLs e encaminhamento à delegacia.","src":"L5"},{"id":"Q32","cat":"leg","q":"A lei pode defender o consumidor e ainda proteger o fornecedor contra abuso?","short":"Sim. A proteção busca equilibrar a relação, mas boa-fé e análise do caso evitam usar o CDC para obter vantagem injusta.","more":"Essa conexão aparece na exceção de erro evidente de preço discutida na aula 02.","src":"L3/L4"},{"id":"Q33","cat":"log","q":"Qual é o objetivo da administração de materiais?","short":"Garantir que o material correto esteja disponível na quantidade, no lugar e no momento adequados, com custo controlado.","more":"Abrange compras, recebimento, armazenagem, estoques, movimentação e distribuição.","src":"G2"},{"id":"Q34","cat":"log","q":"Qual a diferença entre logística e administração de materiais?","short":"Administração de materiais foca no abastecimento e controle dos insumos; logística integra fluxos, armazenagem, transporte e informação.","more":"Os materiais mostram grande relação entre as áreas, com a logística assumindo papel sistêmico nas organizações.","src":"G1"},{"id":"Q35","cat":"log","q":"Por que uma empresa precisa controlar estoques?","short":"Para evitar falta e excesso de produtos, reduzir perdas, manter a operação e não imobilizar recursos desnecessários.","more":"Estoques equilibram disponibilidade e custo; demanda e tempo de reposição influenciam decisões.","src":"G1"},{"id":"Q36","cat":"log","q":"O que diferencia armazenagem de estoque?","short":"Estoque é a quantidade de materiais disponíveis; armazenagem são os processos e locais para receber, guardar, proteger e movimentar esses materiais.","more":"Uma empresa pode ter quantidade correta e armazenagem ruim, gerando atrasos ou avarias.","src":"G3"},{"id":"Q37","cat":"log","q":"Quais são as etapas centrais da armazenagem?","short":"Recebimento, identificação, endereçamento, estocagem, controle, separação de pedidos e expedição.","more":"Etapas integradas reduzem extravios, retrabalho e tempo de separação.","src":"G3"},{"id":"Q38","cat":"log","q":"O que é inventário de materiais?","short":"É conferir as quantidades físicas e comparar com os registros para identificar faltas, excessos e divergências.","more":"Faz parte dos pilares de administração de materiais e melhora confiabilidade dos dados.","src":"G2"},{"id":"Q39","cat":"log","q":"Qual é o dilema entre estoque baixo e bom atendimento?","short":"Estoque baixo reduz custos, mas pode causar ruptura e atrasos. A gestão deve equilibrar economia e nível de serviço.","more":"Decisões levam em conta demanda, custo de armazenagem e consequências da falta de produto.","src":"G1"},{"id":"Q40","cat":"log","q":"Qual a diferença entre PEPS e PVPS?","short":"PEPS prioriza o item recebido primeiro; PVPS prioriza o item com vencimento mais próximo. Para perecíveis, PVPS costuma ser crucial.","more":"Ambos organizam saídas, mas a data de validade pode ser diferente da ordem de entrada.","src":"G3"},{"id":"Q41","cat":"log","q":"O que é WMS e por que ajuda?","short":"É um sistema de gerenciamento de armazéns que controla localização, movimentações e tarefas, reduzindo falhas operacionais.","more":"Com leitores de código e RFID, pode melhorar rastreabilidade e precisão dos dados.","src":"G3"},{"id":"Q42","cat":"log","q":"Como RFID e código de barras diferem na operação?","short":"Ambos ajudam a identificar itens; RFID utiliza identificação por radiofrequência, enquanto código de barras costuma exigir leitura óptica.","more":"O texto didático apresenta ambos como apoio à localização, controle e redução de erros.","src":"G3"},{"id":"Q43","cat":"log","q":"Como a embalagem impacta a logística?","short":"Protege o produto, ajuda na identificação e movimentação e pode reduzir perdas, custos e impacto ambiental.","more":"A apostila considera resistência, manuseio, reaproveitamento e proteção ambiental como critérios.","src":"G1"},{"id":"Q44","cat":"log","q":"Como falta de organização no armazém afeta o cliente?","short":"Provoca separação errada, avarias, atrasos e divergências. O cliente sente diretamente as falhas da operação interna.","more":"A professora liga organização de estoque à qualidade do atendimento e satisfação do consumidor.","src":"G3"},{"id":"Q45","cat":"log","q":"O que é endereço logístico?","short":"É a identificação precisa do local de cada item no armazém, facilitando localização e separação de pedidos.","more":"Endereçamento é etapa distinta da identificação do produto: o primeiro aponta o lugar.","src":"G3"},{"id":"Q46","cat":"log","q":"Quando estoque em excesso pode prejudicar uma empresa?","short":"Quando imobiliza dinheiro, ocupa espaço, eleva custo de armazenagem e aumenta risco de perda ou vencimento.","more":"A gestão deve equilibrar disponibilidade e necessidade real da operação.","src":"G2"},{"id":"Q47","cat":"log","q":"Quais são cinco pilares da administração de materiais?","short":"Compras, gestão de estoques, armazenagem, movimentação de materiais e controle de inventário.","more":"São os cinco pilares enumerados na apostila de Administração de Materiais.","src":"G2"},{"id":"Q48","cat":"log","q":"Uma operação pode ser rápida e ineficiente?","short":"Sim. Velocidade sem controle pode gerar erros, avarias e retrabalho. Eficiência exige custo, qualidade e atendimento equilibrados.","more":"É uma síntese aplicada de armazenagem, logística integrada e administração de materiais.","src":"G1/G3"},{"id":"Q49","cat":"dmn","q":"O que é uma startup?","short":"É um negócio jovem que desenvolve uma solução inovadora, frequentemente com intenção de crescer rapidamente e usar tecnologia.","more":"A apostila destaca equipes pequenas, investimentos, inovação, riscos e adaptação.","src":"D1"},{"id":"Q50","cat":"dmn","q":"O que diferencia uma startup de empresa tradicional?","short":"A startup normalmente experimenta uma solução inovadora e busca crescimento rápido; o negócio tradicional pode operar modelo já consolidado.","more":"A diferença não é apenas idade ou trabalhar na internet; modelo e inovação importam.","src":"D1"},{"id":"Q51","cat":"dmn","q":"Onde fica o Vale do Silício?","short":"Na Califórnia, Estados Unidos. Destaca-se pela concentração de empresas de tecnologia, universidades, investidores e especialistas.","more":"O texto associa seu sucesso a um ecossistema favorável à inovação.","src":"D1"},{"id":"Q52","cat":"dmn","q":"O Vale do Silício teve sucesso apenas por ter grandes empresas?","short":"Não. Universidades, talentos, cultura de inovação, rede de contatos e acesso a investimento formam um ecossistema de apoio.","more":"Empresas se beneficiam de proximidade com pesquisadores, profissionais e financiadores.","src":"D1"},{"id":"Q53","cat":"dmn","q":"Por que startups fracassam mesmo com boas ideias?","short":"Porque uma ideia não garante clientes, investimento ou operação viável. Concorrência, caixa e falta de demanda também pesam.","more":"A apostila identifica incerteza de mercado e dificuldades financeiras como riscos comuns.","src":"D1"},{"id":"Q54","cat":"dmn","q":"O que é intraempreendedorismo?","short":"É agir com iniciativa e inovação dentro de uma organização existente, propondo melhorias sem precisar ser dono do negócio.","more":"Pode ocorrer em cargos diferentes quando alguém identifica um problema e propõe solução concreta.","src":"D2"},{"id":"Q55","cat":"dmn","q":"Qual a diferença entre empreendedor e intraempreendedor?","short":"Empreendedor cria ou conduz um negócio; intraempreendedor melhora e inova em uma organização onde já trabalha.","more":"Ambos exigem criatividade e iniciativa, mas têm contextos e responsabilidades diferentes.","src":"D2"},{"id":"Q56","cat":"dmn","q":"Qual exemplo de intraempreendedorismo está na apostila?","short":"Funcionário do estoque identifica erros de separação e propõe códigos e cores para reduzir falhas e economizar tempo.","more":"O exemplo mostra observação do problema, proposta, aprovação e implementação da melhoria.","src":"D2"},{"id":"Q57","cat":"dmn","q":"Como a empresa pode estimular intraempreendedorismo?","short":"Dando espaço para propostas, valorizando boas ideias e permitindo colaboração, aprendizagem e iniciativa responsável.","more":"O texto destaca reconhecimento, comunicação, liberdade e trabalho em equipe como facilitadores.","src":"D2"},{"id":"Q58","cat":"dmn","q":"Todo funcionário criativo é intraempreendedor?","short":"Não necessariamente. O intraempreendedor identifica oportunidades e transforma iniciativa em melhorias dentro da organização.","more":"Criatividade isolada pode ser um potencial; intraempreendedorismo envolve ação e contribuição.","src":"D2"},{"id":"Q59","cat":"dmn","q":"O que significa escalabilidade num negócio?","short":"É conseguir crescer e atender mais clientes sem aumentar despesas na mesma proporção.","more":"É um complemento explicativo ao crescimento acelerado descrito na apostila de startups.","src":"D1/COMPL"},{"id":"Q60","cat":"dmn","q":"Intraempreendedorismo pode reduzir custos?","short":"Sim. Melhorias internas podem diminuir desperdícios, erros e retrabalho sem exigir criação de uma nova empresa.","more":"O exemplo dos códigos no estoque é uma aplicação direta do conteúdo.","src":"D2"},{"id":"Q61","cat":"dmn","q":"Por que tecnologia não substitui validação do mercado?","short":"Porque uma solução tecnicamente avançada pode não resolver necessidade real. É preciso testar aceitação e capacidade de pagar.","more":"A apostila enfatiza conhecimento do mercado, planejamento e adaptação frente a riscos.","src":"D1"},{"id":"Q62","cat":"dmn","q":"Como ética e intraempreendedorismo se conectam?","short":"Inovar dentro da empresa exige iniciativa, mas também respeito às pessoas e regras; resultado não justifica prejudicar terceiros.","more":"É uma conexão de estudo entre os materiais de ética e DMN, não citação literal de uma apostila.","src":"D2/E1"}],"quiz":[{"cat":"etica","q":"Qual exemplo é improvisação ética?","opts":["Furar fila para perguntar rápido","Mudar atividade por causa da chuva","Fraudar controle para ganhar tempo","Privilegiar amigo na seleção"],"correct":1,"why":"Adaptar planos sem violar direitos é uma forma positiva de flexibilidade.","src":"E2"},{"cat":"etica","q":"O que distingue inclusão de diversidade?","opts":["É só contratar pessoas diferentes","Permitir participação real e remover barreiras","Eliminar qualquer regra","Usar o mesmo equipamento para todos sempre"],"correct":1,"why":"Diversidade é presença; inclusão envolve condições reais de participação.","src":"E3"},{"cat":"etica","q":"O lado negativo do jeitinho afeta sobretudo...","opts":["A cor da marca","A impessoalidade e a confiança","O tamanho do estoque","A velocidade de transporte"],"correct":1,"why":"Privilégios e regras descumpridas enfraquecem igualdade e confiança.","src":"E1"},{"cat":"etica","q":"Uma política acessível deve considerar...","opts":["Somente rampas","Somente comunicação","Barreiras físicas, digitais e organizacionais","Somente o uniforme"],"correct":2,"why":"Acessibilidade é mais ampla do que uma instalação física.","src":"E3"},{"cat":"leg","q":"O que NÃO é elemento típico do vínculo empregatício?","opts":["Subordinação","Pessoalidade","Exclusividade absoluta","Remuneração"],"correct":2,"why":"Exclusividade absoluta não é requisito obrigatório descrito entre os cinco elementos.","src":"L2"},{"cat":"leg","q":"Prazo atual do art. 29 da CLT para anotações?","opts":["24 horas","48 horas","5 dias úteis","30 dias"],"correct":2,"why":"A redação vigente prevê cinco dias úteis; 48 horas aparece em material antigo.","src":"L2/ATUAL"},{"cat":"leg","q":"Compra feita pela internet: prazo geral de arrependimento?","opts":["2 dias","7 dias","15 dias","30 dias"],"correct":1,"why":"A regra do art. 49 trata de contratação fora do estabelecimento.","src":"L4"},{"cat":"leg","q":"O juiz inverte sempre o ônus da prova?","opts":["Sim, automaticamente","Não, depende das condições legais","Somente para empresas","Nunca"],"correct":1,"why":"A inversão depende da análise de requisitos do CDC.","src":"L3"},{"cat":"leg","q":"Vício aparente em produto durável: prazo geral?","opts":["7 dias","30 dias","90 dias","2 anos"],"correct":2,"why":"A apostila distingue 30 dias (não duráveis) e 90 dias (duráveis).","src":"L4"},{"cat":"leg","q":"O stalking exige, em regra...","opts":["Uma crítica isolada","Perseguição reiterada","Uma postagem anônima qualquer","Discussão de preço"],"correct":1,"why":"A reiteração integra a descrição do art. 147-A.","src":"L5"},{"cat":"log","q":"Qual prática dá prioridade à validade?","opts":["PEPS","PVPS","Inventário anual","Cross-docking"],"correct":1,"why":"PVPS prioriza o item com vencimento mais próximo.","src":"G3"},{"cat":"log","q":"O que compara estoque físico e registros?","opts":["Inventário","Publicidade","Precificação","Intraempreendedorismo"],"correct":0,"why":"Inventário identifica divergências entre as quantidades contadas e registradas.","src":"G2"},{"cat":"log","q":"WMS é utilizado principalmente para...","opts":["Contratar funcionários","Gerenciar armazéns","Redigir contratos","Cobrar impostos"],"correct":1,"why":"WMS facilita localização, registros, movimentações e tarefas de armazenagem.","src":"G3"},{"cat":"log","q":"Estoque alto sempre é positivo?","opts":["Sim","Não, ele eleva custos e imobiliza capital","Sim, se há etiquetas","Só no varejo"],"correct":1,"why":"É necessário equilibrar disponibilidade e custo.","src":"G1"},{"cat":"log","q":"Qual etapa define o local exato do item?","opts":["Endereçamento","Faturamento","Publicidade","Precificação"],"correct":0,"why":"Endereçamento localiza cada produto no armazém.","src":"G3"},{"cat":"dmn","q":"Quem é intraempreendedor?","opts":["Só o dono","Profissional que inova dentro da empresa","Apenas investidor","Somente cliente"],"correct":1,"why":"O profissional pode inovar sem possuir a empresa.","src":"D2"},{"cat":"dmn","q":"O Vale do Silício é...","opts":["Uma empresa","Uma região da Califórnia","Uma cidade brasileira","Um fundo público único"],"correct":1,"why":"É uma região conhecida pela concentração de empresas, universidades e investidores.","src":"D1"},{"cat":"dmn","q":"Para uma startup, boa ideia garante sucesso?","opts":["Sim","Não; há riscos de mercado e finanças","Somente com logo","Sim, se viralizar"],"correct":1,"why":"Aceitação, execução, capital e concorrência importam.","src":"D1"},{"cat":"dmn","q":"Qual exemplo está na apostila de intraempreendedorismo?","opts":["Criar cidade","Códigos e cores no estoque","Comprar concorrente","Vender ação"],"correct":1,"why":"O funcionário propõe identificação para reduzir erros.","src":"D2"},{"cat":"dmn","q":"Crescer com menor aumento proporcional de custos define...","opts":["Escalabilidade","Inventário","Isenção","Subordinação"],"correct":0,"why":"Escalabilidade é conceito complementar à discussão de startups.","src":"D1/COMPL"}],"manualSources":[{"id":"E1","cat":"Ética","title":"O Jeitinho Brasileiro — 4º bimestre","kind":"Material de aula"},{"id":"E2","cat":"Ética","title":"Significado do Jeitinho brasileiro","kind":"Material de aula"},{"id":"E3","cat":"Ética","title":"Acessibilidade e inclusão no ambiente de trabalho","kind":"Material de aula"},{"id":"L1","cat":"Legislação","title":"A CLT — Consolidação das Leis do Trabalho","kind":"Material de aula"},{"id":"L2","cat":"Legislação","title":"Direito do Trabalho — aula 01","kind":"Material de aula"},{"id":"L3","cat":"Legislação","title":"Direito do Consumidor — aula 01","kind":"Material de aula"},{"id":"L4","cat":"Legislação","title":"Direito do Consumidor — aula 02","kind":"Material de aula"},{"id":"L5","cat":"Legislação","title":"Crime de perseguição / stalking","kind":"Material de aula"},{"id":"G1","cat":"Logística","title":"Administração de materiais e logística dentro da organização","kind":"Material de aula"},{"id":"G2","cat":"Logística","title":"Administração de Materiais — 4º bimestre","kind":"Material de aula"},{"id":"G3","cat":"Logística","title":"Armazenamento na logística: importância e funções","kind":"Material de aula"},{"id":"D1","cat":"DMN","title":"Startups e o Vale do Silício","kind":"Material de aula"},{"id":"D2","cat":"DMN","title":"Intraempreendedorismo: inovação e iniciativa","kind":"Material de aula"}],"officialSources":[{"title":"CLT — Consolidação das Leis do Trabalho","cat":"Legislação","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del5452compilado.htm","tag":"Texto legal oficial"},{"title":"CDC — Código de Defesa do Consumidor","cat":"Legislação","url":"https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm","tag":"Texto legal oficial"},{"title":"Lei 14.132/2021 — Crime de perseguição","cat":"Legislação","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14132.htm","tag":"Texto legal oficial"},{"title":"Lei 13.146/2015 — Lei Brasileira de Inclusão","cat":"Ética","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","tag":"Texto legal oficial"},{"title":"Orientações de direito do consumidor","cat":"Legislação","url":"https://www.procon.sp.gov.br/legislacao-federal/","tag":"Órgão de defesa do consumidor"},{"title":"Modelo de negócio Canvas — nove blocos","cat":"DMN","url":"https://meuatendimento.sebrae.com.br/sites/PortalSebrae/ufs/pe/artigos/canvas-ajuda-a-estruturar-seus-modelo-de-negocio%2C1d20d5359defe610VgnVCM1000004c00210aRCRD","tag":"Sebrae • referência complementar"}],"connections":[{"title":"Ética × Legislação","tag":"Conduta e obrigação","text":"Uma empresa pode cumprir o mínimo formal e ainda tratar pessoas de forma desrespeitosa. Ética pede reflexão sobre impacto coletivo; legislação estabelece obrigações e direitos exigíveis.","example":"No atendimento, a pessoa respeita direitos do consumidor e também evita discriminação e tratamento humilhante."},{"title":"Logística × Legislação","tag":"Processos e responsabilidade","text":"Controle de estoque não é somente eficiência: processos ruins geram atrasos, descumprimento de oferta e dificuldades para cumprir direitos do consumidor.","example":"Um produto anunciado sem estoque deve ser tratado com transparência e observância das regras de oferta."},{"title":"DMN × Logística","tag":"Ideia e execução","text":"Uma proposta inovadora só se sustenta se consegue transformar o modelo de negócio em operações viáveis, com fornecimento, armazenamento e entrega.","example":"Ao idealizar um minimercado, testar reposição e giro de itens é tão importante quanto desenhar a proposta de valor."},{"title":"DMN × Ética","tag":"Inovação responsável","text":"Intraempreendedorismo amplia possibilidades de melhoria, mas não justifica burlar controles ou eliminar acessibilidade para reduzir custos.","example":"Automatizar um atendimento pode gerar ganhos sem impedir alternativas acessíveis a quem precisa."}],"cases":[{"id":"s1","prompt":"Uma pessoa pede para ser atendida antes de todos porque está com pressa. Qual é o primeiro critério de decisão?","choices":["A necessidade de obter vantagem pessoal","As regras de atendimento e os direitos dos demais","O potencial de vender mais"],"correct":1,"why":"Criatividade e empatia não dispensam critérios transparentes e tratamento justo. Há situações de prioridade legal, que precisam ser identificadas corretamente."},{"id":"s2","prompt":"Uma loja recebeu mercadorias com validades diferentes. Qual prática reduz risco de vencimento?","choices":["Priorizar itens que vencem primeiro, quando aplicável","Separar qualquer pedido aleatoriamente","Guardar os itens mais antigos no fundo"],"correct":0,"why":"PVPS (primeiro que vence, primeiro que sai) é uma referência operacional útil em perecíveis, junto do controle adequado de condições de armazenagem."},{"id":"s3","prompt":"Uma ideia de aplicativo está pronta no papel. Qual próximo passo gera aprendizagem real?","choices":["Investir tudo em propaganda imediatamente","Pressupor que todas as pessoas vão gostar","Testar o problema com usuários e observar uso"],"correct":2,"why":"Validar necessidade, proposta e operação reduz decisões baseadas apenas em intuição."}],"glossary":[{"term":"Equidade","desc":"Práticas que consideram barreiras e condições diferentes para viabilizar oportunidades justas."},{"term":"Isonomia","desc":"Princípio de tratamento igual perante as regras aplicáveis, com atenção às distinções legalmente justificadas."},{"term":"Acessibilidade","desc":"Condições de utilização autônoma e segura de espaços, serviços e informações, removendo barreiras."},{"term":"Vínculo empregatício","desc":"Relação jurídica cujos elementos incluem pessoa física, pessoalidade, não eventualidade, subordinação e remuneração."},{"term":"Ruptura de estoque","desc":"Falta de um item quando ele é necessário, gerando perda de venda ou interrupção operacional."},{"term":"CTPS","desc":"Carteira de Trabalho e Previdência Social, registro de vínculos e informações profissionais."},{"term":"Oferta vinculante","desc":"Publicidade ou informação suficientemente precisa pode obrigar fornecedor nos termos do CDC."},{"term":"Inventário","desc":"Conferência física de itens em comparação com registros de sistema e controles."},{"term":"PEPS","desc":"Primeiro que entra, primeiro que sai: prioridade de movimentação dos itens mais antigos."},{"term":"PVPS","desc":"Primeiro que vence, primeiro que sai: prioridade conforme validade."},{"term":"WMS","desc":"Sistema de gerenciamento de armazéns usado para apoiar endereçamento, movimentos e rastreabilidade."},{"term":"Intraempreendedorismo","desc":"Iniciativa de melhoria e inovação dentro de uma organização já existente."},{"term":"Escalabilidade","desc":"Capacidade de crescer atendimento ou entrega sem aumentar custos na mesma proporção."},{"term":"Modelo de negócio","desc":"Lógica pela qual uma iniciativa gera, entrega e captura valor; pode ser mapeada em nove blocos pelo Canvas."}]};